items.solution:
function isDangling(commitId, refs, commits) {
  function isReachableFrom(startId, targetId) {
    let cur = startId;
    while (cur !== null && cur !== undefined) {
      if (cur === targetId) return true;
      cur = commits[cur] ? commits[cur].parent : null;
    }
    return false;
  }
  return !refs.some((refId) => isReachableFrom(refId, commitId));
}

